let enrolmentDraft=null,enrolmentValues=null,enrolmentBusy=false;const el=id=>document.getElementById(id);const raceNames={Terran:'Helion',Cathaar:'Velari',Xandathrii:'Nexari',Zikonian:'Kryth',Eitraides:'Auralis',AstraNexus:'Astra Nexus',LCARS:'Stellar Federation',Borg:'Assimilation Nexus',Stargate:'Gatebound Legacy',DoctorWho:'Temporal Voyager',Battlestar:'Colonial Vanguard'};async function enrolmentRequest(body){const r=await fetch('/api/planet-enrolment',{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Registration unavailable.');return d;}async function loadEnrolment(){try{enrolmentDraft=await enrolmentRequest();if(enrolmentDraft.confirmed){location.replace('/game');return;}const t=enrolmentDraft.planetType;el('typeName').textContent=t.name;el('planetArtwork').src='/assets/planets/'+t.id+'.svg';el('planetArtwork').alt=t.name+' orbital survey';el('lore').textContent=t.lore;const stats=[['Habitability',t.habitability+'%'],['Biodiversity',t.biodiversity+'%'],['Moisture',t.moisture+'%'],['Rockiness',t.rockiness+'%'],['Starting residents',t.basePopulation.toLocaleString()],['Growth modifier',(t.growthPercent>=0?'+':'')+t.growthPercent+'%'],['Mining bonus','+'+(t.basePopulation*.001).toFixed(3)+'%'],['CU / RP bonus','+'+Math.floor(t.basePopulation/100)],['Housing',t.basePopulation.toLocaleString()]];for(const [label,value] of stats){const box=document.createElement('div'),small=document.createElement('small'),b=document.createElement('b');small.textContent=label;b.textContent=value;box.append(small,b);el('stats').append(box);}el('ruler').value=enrolmentDraft.username;el('planetName').value=enrolmentDraft.username+"'s planet";for(const kind of ['race','theme'])for(const v of enrolmentDraft[kind==='race'?'races':'themes']){const o=document.createElement('option');o.value=v;o.textContent=raceNames[v]||v;el(kind).append(o);}el('content').hidden=false;el('loading').hidden=true;}catch(e){el('loading').textContent=e.message;}}
el('charter').addEventListener('submit',e=>{e.preventDefault();enrolmentValues={ruler:el('ruler').value.trim(),planetName:el('planetName').value.trim(),race:el('race').value,theme:el('theme').value,generation:enrolmentDraft.generation,confirmation:true};el('reviewValues').replaceChildren();for(const [label,value] of [['Ruler',enrolmentValues.ruler],['Planet',enrolmentValues.planetName],['Race',raceNames[enrolmentValues.race]],['Theme',raceNames[enrolmentValues.theme]||enrolmentValues.theme],['Planet type',enrolmentDraft.planetType.name],['Starting population',enrolmentDraft.planetType.basePopulation]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;el('reviewValues').append(dt,dd);}el('confirmation').showModal();});el('back').onclick=()=>el('confirmation').close();el('enter').onclick=async()=>{if(enrolmentBusy)return;enrolmentBusy=true;el('enter').disabled=true;try{await enrolmentRequest(enrolmentValues);localStorage.setItem('starfall-enrolment-theme',enrolmentValues.theme);location.replace('/game');}catch(e){el('confirmError').textContent=e.message;enrolmentBusy=false;el('enter').disabled=false;}};loadEnrolment();

el('theme').addEventListener('change',()=>{document.body.dataset.skin=el('theme').value;});